const updateApprovalConfigById = async (id, body) => {
  if (await ApprovalConfig.findOne(buildDuplicateCheckQuery(body, id))) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'There is already a config with this configuration');
  }
  validateConfig(body)
  if (!await ApprovalConfig.findOne({_id:id})) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'Approval Config not found')
  }
  if (await Approval.findOne({ approvalConfigId: id, status: statusEnums.APPROVAL_IN_PROGRESS })) {
    throw new ApiError(
      httpStatus.BAD_REQUEST,
      'There are pending approvals for the configuration. Please let them close first before trying to update the configuration'
    );
  }

const deleteApprovalConfigById = async (id) => {
  if (await Approval.findOne({ approvalConfigId: id, status: statusEnums.APPROVAL_IN_PROGRESS })) {
    throw new ApiError(
      httpStatus.BAD_REQUEST,
      'There are pending approvals for the configuration. Please let them close first before trying to update the configuration'
    );
  }

  await ApprovalConfig.findByIdAndUpdate(id, { archive: true });
};

const validateConfig = (body) => {
  const { locationType, stages } = body;
  if (!locationType || locationType === locationTypes.ho) {
    stages?.forEach?.((stage) => {
      const allowedRole = parseInt(stage?.allowedRole);
      if (
        allowedRole === parseInt(maintenance_dept_details.area_manager_role_id) ||
        allowedRole === parseInt(maintenance_dept_details.regional_manager_role_id)
      ) {
        throw new ApiError(httpStatus.BAD_REQUEST, 'Area/ Regional Mangager role can be assigned only for store locations');
      }
    });
  }

let linkedPR = null;
try {
  if (body.purchaseRequestId) {
    linkedPR = await PurchaseRequest.findById(body.purchaseRequestId);
    if (!linkedPR || linkedPR.status !== statusEnums.APPROVED) {
      throw new ApiError(httpStatus.BAD_REQUEST, 'PO can only be created from an approved PR');
    }
    if (!(await canConvertPRToPO(user, linkedPR))) {
      throw new ApiError(httpStatus.FORBIDDEN, 'You do not have permission to create a Purchase Order from this Purchase Requisition');
    }
    body.department = user.department ?? (await getProcurementDepartmentId());
    validateDeliveryStoreAgainstPR(linkedPR, body.deliveryLocationId);
    body.items = resolvePOItemsAgainstPR(linkedPR, body.items, body.deliveryLocationId);
    await validateRateContractItems(body.items, body.vendorCode, body.poDate || new Date());

} else {
  if (!body.department) {
    throw new ApiError(httpStatus.BAD_REQUEST, 'Department is required');
  }

const budget = await budgetService.getOneBudget({ _id: body.budget });
if (!budget.initialApproval && budget.status != statusEnums.APPROVED) {
  throw new ApiError(httpStatus.BAD_REQUEST, `PO can not be raised for unapproved budget ${budget.id}`);
}

const validateItems = async (items) => {
  const lineItemIds = [...new Set(items.map((i) => i.lineItem))];
  const lineItems = await LineItem.find({ _id: { $in: lineItemIds } });

  const lineItemMap = new Map(lineItems.map((li) => [String(li._id), li]));

  for (const item of items) {
    const lineItem = lineItemMap.get(String(item.lineItem));
    if (!lineItem) {
      throw new ApiError(`LineItem not found for item: ${item.item}`);
    }

    if (lineItem.category?.isTicketRequired) {
      if (!item.ticketNumber || !item.ticketCreationDate) {
        throw new ApiError(
          `Ticket Number and Ticket Creation Date are mandatory for items in category: ${lineItem.category.name}`
        );
      }
    }
  }

